previewCss:
.darma-loader-tuning-fork {
  position: relative;
  width: 34px;
  height: 52px;
  animation: darma-loader-tuning-fork-vib 0.14s ease-in-out infinite;
}
.darma-loader-tuning-fork::before {
  content: "";
  position: absolute;
  bottom: 14px;
  left: 8px;
  width: 18px;
  height: 6px;
  background: var(--loader-color, #6366f1);
  border-radius: 3px;
}
.darma-loader-tuning-fork::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 6px;
  height: 16px;
  margin-left: -3px;
  border-radius: 0 0 3px 3px;
  background: var(--loader-color, #6366f1);
}
.darma-loader-tuning-fork i {
  position: absolute;
  bottom: 18px;
  width: 6px;
  height: 32px;
  border-radius: 3px 3px 0 0;
  background: var(--loader-color, #6366f1);
}
.darma-loader-tuning-fork i:nth-child(1) { left: 8px; }
.darma-loader-tuning-fork i:nth-child(2) { right: 8px; }
@keyframes darma-loader-tuning-fork-vib {
  0%, 100% { transform: translateX(-1.5px); }
  50% { transform: translateX(1.5px); }
}

